module parity_8bit (
    input [7:0] in,
    output out
);

    // Using iterative XOR to compute parity
    // out = in[7] ^ in[6] ^ in[5] ^ in[4] ^ in[3] ^ in[2] ^ in[1] ^ in[0];

    // Alternatively, using a more structured approach for clarity,
    // though the direct XOR is more efficient in terms of gate count for synthesis.
    // We will stick to the direct XOR as per the reasoning process.

    assign out = in[7] ^ in[6] ^ in[5] ^ in[4] ^ in[3] ^ in[2] ^ in[1] ^ in[0];

endmodule

