module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire en0, en1, en2, en3;

    // Deconstruct the input bus
    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    // Generate enable signals based on select inputs
    // en0 = ~sel[1] & ~sel[0]
    assign en0 = ~sel[1] & ~sel[0];
    // en1 = ~sel[1] & sel[0]
    assign en1 = ~sel[1] & sel[0];
    // en2 = sel[1] & ~sel[0]
    assign en2 = sel[1] & ~sel[0];
    // en3 = sel[1] & sel[0]
    assign en3 = sel[1] & sel[0];

    // Combine enable signals with data inputs and OR them for the output
    // out = (d0 & en0) | (d1 & en1) | (d2 & en2) | (d3 & en3)
    assign out = (d0 & en0) | (d1 & en1) | (d2 & en2) | (d3 & en3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire en0, en1, en2, en3;

    // Enable signal generation based on select inputs
    assign en0 = ~sel[1] & ~sel[0]; // sel = 00
    assign en1 = ~sel[1] & sel[0];  // sel = 01
    assign en2 = sel[1] & ~sel[0];  // sel = 10
    assign en3 = sel[1] & sel[0];   // sel = 11

    // Combine enable signals with data inputs and OR them for the final output
    assign out = (in[0] & en0) | (in[1] & en1) | (in[2] & en2) | (in[3] & en3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire en0, en1, en2, en3;

    // Decode select signals to generate enable signals
    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    // Enable for d0 (sel = 00)
    assign en0 = ~sel[1] & ~sel[0];

    // Enable for d1 (sel = 01)
    assign en1 = ~sel[1] & sel[0];

    // Enable for d2 (sel = 10)
    assign en2 = sel[1] & ~sel[0];

    // Enable for d3 (sel = 11)
    assign en3 = sel[1] & sel[0];

    // Combine enable signals with data inputs and OR them
    assign out = (d0 & en0) | (d1 & en1) | (d2 & en2) | (d3 & en3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire enable0, enable1, enable2, enable3;

    // Deconstruct the input bus
    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    // Generate enable signals based on select inputs
    // sel = 00 -> enable0 = 1
    assign enable0 = ~sel[1] & ~sel[0];
    // sel = 01 -> enable1 = 1
    assign enable1 = ~sel[1] & sel[0];
    // sel = 10 -> enable2 = 1
    assign enable2 = sel[1] & ~sel[0];
    // sel = 11 -> enable3 = 1
    assign enable3 = sel[1] & sel[0];

    // Combine enable signals with data inputs
    wire term0, term1, term2, term3;
    assign term0 = d0 & enable0;
    assign term1 = d1 & enable1;
    assign term2 = d2 & enable2;
    assign term3 = d3 & enable3;

    // OR the terms to get the final output
    assign out = term0 | term1 | term2 | term3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire s0, s1;
    wire en0, en1, en2, en3;

    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    assign s0 = sel[0];
    assign s1 = sel[1];

    // Enable signals for each input
    assign en0 = (~s1) & (~s0); // sel = 00
    assign en1 = (~s1) & s0;   // sel = 01
    assign en2 = s1 & (~s0);   // sel = 10
    assign en3 = s1 & s0;      // sel = 11

    // Output logic: OR of (enable * data) for each input
    assign out = (en0 & d0) | (en1 & d1) | (en2 & d2) | (en3 & d3);

endmodule

