module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire s0, s1;
    wire en0, en1, en2, en3;

    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    assign s0 = sel[0];
    assign s1 = sel[1];

    // Enable signal generation for each input
    // en0 = ~s1 & ~s0  (select 00)
    assign en0 = ~s1 & ~s0;
    // en1 = ~s1 & s0   (select 01)
    assign en1 = ~s1 & s0;
    // en2 = s1 & ~s0   (select 10)
    assign en2 = s1 & ~s0;
    // en3 = s1 & s0    (select 11)
    assign en3 = s1 & s0;

    // Combine enable signals with data inputs
    wire y0, y1, y2, y3;
    assign y0 = en0 & d0;
    assign y1 = en1 & d1;
    assign y2 = en2 & d2;
    assign y3 = en3 & d3;

    // Aggregate the partial outputs
    assign out = y0 | y1 | y2 | y3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0_en;
    wire d1_en;
    wire d2_en;
    wire d3_en;

    // Enable for d0 (sel = 00)
    assign d0_en = ~sel[1] & ~sel[0];

    // Enable for d1 (sel = 01)
    assign d1_en = ~sel[1] & sel[0];

    // Enable for d2 (sel = 10)
    assign d2_en = sel[1] & ~sel[0];

    // Enable for d3 (sel = 11)
    assign d3_en = sel[1] & sel[0];

    // Output logic: OR of (enable AND data_in)
    assign out = (d0_en & in[0]) | (d1_en & in[1]) | (d2_en & in[2]) | (d3_en & in[3]);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire d0, d1, d2, d3;
    wire s0, s1;
    wire en0, en1, en2, en3;

    // Deconstruct inputs
    assign d0 = in[0];
    assign d1 = in[1];
    assign d2 = in[2];
    assign d3 = in[3];

    assign s0 = sel[0];
    assign s1 = sel[1];

    // Generate enable signals for each input
    // en0 = (~s1) & (~s0)
    assign en0 = ~s1 & ~s0;
    // en1 = (~s1) & s0
    assign en1 = ~s1 & s0;
    // en2 = s1 & (~s0)
    assign en2 = s1 & ~s0;
    // en3 = s1 & s0
    assign en3 = s1 & s0;

    // Combine enable signals with data inputs and OR them for the output
    // out = (d0 & en0) | (d1 & en1) | (d2 & en2) | (d3 & en3)
    assign out = (d0 & en0) | (d1 & en1) | (d2 & en2) | (d3 & en3);

endmodule

