module seven_segment_decoder (
    input [3:0] digit,
    output reg [6:0] segments
);

// Mapping from 4-bit binary input to 7-segment display output for common anode.
// Segments are ordered: a, b, c, d, e, f, g
// 0: 0111111 (a,b,c,d,e,f)
// 1: 0000110 (b,c)
// 2: 1011011 (a,b,g,e,d)
// 3: 1001111 (a,b,g,c,d)
// 4: 1100110 (f,g,b,c)
// 5: 1101101 (a,f,g,c,d)
// 6: 1111101 (a,f,g,e,c,d)
// 7: 0000111 (a,b,c)
// 8: 1111111 (a,b,c,d,e,f,g)
// 9: 1101111 (a,b,g,c,d,f)
// A: 1110111 (a,b,g,e,f,c)
// B: 1111100 (f,e,d,c,g)
// C: 1000001 (a,f,e,d)
// D: 1011110 (b,c,d,e,g)
// E: 1111001 (a,f,e,d,g)
// F: 1110001 (a,f,e,g)

always @(*) begin
    case (digit)
        4'd0: segments = 7'b0111111; // 0
        4'd1: segments = 7'b0000110; // 1
        4'd2: segments = 7'b1011011; // 2
        4'd3: segments = 7'b1001111; // 3
        4'd4: segments = 7'b1100110; // 4
        4'd5: segments = 7'b1101101; // 5
        4'd6: segments = 7'b1111101; // 6
        4'd7: segments = 7'b0000111; // 7
        4'd8: segments = 7'b1111111; // 8
        4'd9: segments = 7'b1101111; // 9
        4'd10: segments = 7'b1110111; // A
        4'd11: segments = 7'b1111100; // B
        4'd12: segments = 7'b1000001; // C
        4'd13: segments = 7'b1011110; // D
        4'd14: segments = 7'b1111001; // E
        4'd15: segments = 7'b1110001; // F
        default: segments = 7'b0000000; // All segments off for undefined inputs
    endcase
end

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

    // The problem states that SystemVerilog is not supported, so we will use
    // Verilog-2001 syntax for continuous assignments.

    // The highest priority bit is in[3]. If it's 1, then code should be 2'b11.
    // If in[3] is 0, then we check in[2]. If in[2] is 1, then code should be 2'b10.
    // If in[3] and in[2] are 0, then we check in[1]. If in[1] is 1, then code should be 2'b01.
    // If in[3], in[2], and in[1] are 0, then we check in[0]. If in[0] is 1, then code should be 2'b00.
    // If all input bits are 0, then the output code should be 2'b00.

    always @(*) begin
        if (in[3] == 1'b1) begin
            code = 2'b11;
        end else if (in[2] == 1'b1) begin
            code = 2'b10;
        end else if (in[1] == 1'b1) begin
            code = 2'b01;
        end else if (in[0] == 1'b1) begin
