module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    parameter IDLE = 2'b00;
    parameter COLLECTING_COINS = 2'b01;
    parameter DISPENSING_ITEM = 2'b10;

    // Internal signals
    reg [1:0] current_state;
    reg [1:0] next_state;
    reg [7:0] coin_count; // Assuming max 255 coins for simplicity
    reg dispense_flag;

    // State Register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next State Logic and Output Logic
    always @(*) begin
        next_state = current_state; // Default to staying in current state
        dispense_flag = 1'b0;      // Default to not dispensing
        coin_count = coin_count;   // Default to keeping current coin count

        case (current_state)
            IDLE: begin
                if (coin_inserted) begin
                    next_state = COLLECTING_COINS;
                    coin_count = 1; // Start counting from 1
                end else begin
                    next_state = IDLE;
                    coin_count = 0; // Ensure count is 0 when idle
                end
            end

            COLLECTING_COINS: begin
                if (coin_inserted) begin
                    next_state = COLLECTING_COINS;
                    coin_count = coin_count + 1;
                end else if (item_selected) begin
                    // Check if enough coins are collected (assuming 1 coin is enough for any item for simplicity)
                    if (coin_count >= 1) begin
                        next_state = DISPENSING_ITEM;
                    end else begin
                        next_state = COLLECTING_COINS; // Stay in collecting if not enough coins
                    end
                end else begin
                    next_state = COLLECTING_COINS;
                end
            end

            DISPENSING_ITEM: begin
                dispense_flag = 1'b1; // Signal to dispense
                // After dispensing, transition back to IDLE
                // In a real system, this might depend on a 'dispense_done' signal
                next_state = IDLE;
                coin_count = 0; // Reset coin count after dispensing
            end

            default: begin
                next_state = IDLE;
                coin_count = 0;
            end
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

