    assign c1_2 = (p0[3] & ((p1[2] << 1) ^ c1_1)) | (((p1[2] << 1) & c1_1));
    assign sum0[4] = (p1[3] << 1) ^ c1_2;
    assign c1_3 = (p1[3] << 1) & c1_2;
