module feistel_cipher (
    input wire [7:0] data_in,
    input wire [3:0] key,
    output wire [7:0] data_out
);

    // Declare Internal Signals
    wire [3:0] left;
    wire [3:0] right;
    wire [3:0] new_right;
    wire [3:0] output_left;
    wire [3:0] output_right;

    // Design Module: Splitting the input
    assign left = data_in[7:4];
    assign right = data_in[3:0];

    // Design Module: Round function (XOR with key)
    assign new_right = right ^ key;

    // Design Module: Combining and swapping for encryption
    assign output_left = new_right; // The result of round function becomes the new left half
