    // G_ACCEL is 4 bits (10), t_squared is 16 bits.
    // G_ACCEL * t_squared can be up to 4 + 16 = 20 bits.
    // We need at least 24 bits as per problem statement for g * t^2.
    wire [23:0] g_times_t_squared;

    // Design Module: Computation steps using continuous assignments

    // Step 1: Square the time input t
    assign t_squared = t_in * t_in;

    // Step 2: Multiply the result by constant gravity g
    // Extend t_squared to 24 bits before multiplication to ensure sufficient width.
    // G_ACCEL is a parameter, which can be treated as a constant.
    // The multiplication result will be 24 bits.
    assign g_times_t_squared = G_ACCEL * {{16{1'b0}}, t_squared};

    // Step 3: Divide the product by 2 to calculate the displacement d
    // The result of division by 2 will be 23 bits.
    // The output distance is 16 bits, so we need to truncate or ensure the result fits.
    // Since the output is 16 bits, we take the lower 16 bits of the result.
    // The formula d = (g * t^2) / 2.
